import { defineConfig } from "@kubb/core";
import { pluginClient } from "@kubb/plugin-client";
import { pluginOas } from "@kubb/plugin-oas";
import { pluginTs } from "@kubb/plugin-ts";
import { pluginZod } from "@kubb/plugin-zod";
import { fileURLToPath } from "node:url";

const clientRoot = fileURLToPath(new URL("./", import.meta.url));

/** Kubb owns the generated API contract for the hevy-client workspace. */
export default defineConfig({
	root: clientRoot,
	input: {
		path: fileURLToPath(new URL("../../openapi-spec.json", import.meta.url)),
	},
	output: {
		// Kubb resolves output paths from the workspace process directory.
		path: "./src/generated",
		clean: true,
		format: "oxfmt",
	},
	plugins: [
		pluginOas({ output: { path: "./client" } }),
		pluginTs({ output: { path: "./client/types" } }),
		pluginClient({
			output: { path: "./client/api" },
			// Keep the generated operations on the runtime-neutral client adapter.
			// Kubb's bundled fetch template sets `credentials`, which Cloudflare's
			// RequestInit intentionally does not support.
			importPath: "../../../fetch.ts",
		}),
		pluginZod({ output: { path: "./client/schemas" } }),
	],
});

#!/usr/bin/env node
import {
	cp,
	mkdtemp,
	readFile,
	readdir,
	rm,
	stat,
	symlink,
	writeFile,
} from "node:fs/promises";
import { tmpdir } from "node:os";
import { dirname, join, relative, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { spawn } from "node:child_process";
import { createRequire } from "node:module";
import { fixOpenAPISpec, validateOpenAPISpec } from "./openapi-spec.js";
import { isString } from "./runtime-value-predicates.mjs";

const require = createRequire(import.meta.url);
const repositoryRoot = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const clientRoot = resolve(repositoryRoot, "packages/hevy-client");
const generatedRelative = "src/generated";
const generatedRoot = resolve(clientRoot, generatedRelative);
const curatedBarrels = ["src/types.ts", "src/schemas.ts"];
const DEFAULT_COMMAND_TIMEOUT_MS = 120_000;
const DEFAULT_COMMAND_KILL_SIGNAL = "SIGTERM";
const SIGKILL_GRACE_PERIOD_MS = 2_000;

async function collectFiles(directory) {
	try {
		const entries = await readdir(directory, { withFileTypes: true });
		const files = [];
		for (const entry of entries) {
			const path = join(directory, entry.name);
			if (entry.isDirectory()) files.push(...(await collectFiles(path)));
			else files.push(path);
		}
		return files;
	} catch (error) {
		if (error?.code === "ENOENT") return [];
		throw error;
	}
}

function relativePath(root, path) {
	return relative(root, path).replaceAll("\\", "/");
}

export function isNodeModulesPath(path) {
	return path.split(/[\\/]+/).includes("node_modules");
}

/**
 * Compare two generated output trees without mutating either tree.
 *
 * The result is intentionally a list rather than a boolean so CI output
 * identifies the exact generated file that needs review.
 */
export async function compareDirectoryTrees(expectedRoot, actualRoot) {
	const expectedFiles = new Map(
		(await collectFiles(expectedRoot)).map((path) => [
			relativePath(expectedRoot, path),
			path,
		]),
	);
	const actualFiles = new Map(
		(await collectFiles(actualRoot)).map((path) => [
			relativePath(actualRoot, path),
			path,
		]),
	);
	const differences = [];
	const paths = new Set([...expectedFiles.keys(), ...actualFiles.keys()]);

	for (const path of [...paths].sort((left, right) =>
		left.localeCompare(right),
	)) {
		const expectedPath = expectedFiles.get(path);
		const actualPath = actualFiles.get(path);
		if (!expectedPath) {
			differences.push(`unexpected generated file: ${path}`);
			continue;
		}
		if (!actualPath) {
			differences.push(`missing generated file: ${path}`);
			continue;
		}

		const [expected, actual] = await Promise.all([
			readFile(expectedPath),
			readFile(actualPath),
		]);
		if (!expected.equals(actual)) {
			differences.push(`generated file differs: ${path}`);
		}
	}

	return differences;
}

/**
 * Return every file under a repository-root `src` directory. The repository
 * intentionally has no runtime root source tree; a non-empty result means a
 * generator escaped its package output closure.
 */
export async function findForbiddenRootSourceFiles(root) {
	const sourceRoot = resolve(root, "src");
	try {
		const sourceStats = await stat(sourceRoot);
		if (!sourceStats.isDirectory()) return ["src"];
	} catch (error) {
		if (error?.code === "ENOENT") return [];
		throw error;
	}

	const files = await collectFiles(sourceRoot);
	return files.length > 0
		? files.map((path) => relativePath(root, path)).sort()
		: ["src"];
}

function generatedTargetCandidates(specifier) {
	const target = specifier.slice("./generated/".length);
	if (target.includes("..")) return [];
	const candidates = [target];
	if (target.endsWith(".js")) {
		candidates.push(target.slice(0, -3) + ".ts");
		candidates.push(target.slice(0, -3) + ".json");
	}
	return candidates;
}

/**
 * Ensure curated public barrels only reference generated files that exist.
 * This keeps an upstream endpoint/schema change from silently leaving a
 * broken package API after regeneration.
 */
export async function findCuratedBarrelDrift(packageRoot) {
	const generatedDirectory = resolve(packageRoot, generatedRelative);
	const failures = [];
	const importPattern = /from\s+["'](\.\/generated\/[^"']+)["']/g;

	for (const barrel of curatedBarrels) {
		const barrelPath = resolve(packageRoot, barrel);
		let source;
		try {
			source = await readFile(barrelPath, "utf8");
		} catch (error) {
			if (error?.code === "ENOENT") {
				failures.push(`missing curated barrel: ${barrel}`);
				continue;
			}
			throw error;
		}

		for (const match of source.matchAll(importPattern)) {
			const specifier = match[1];
			const candidates = generatedTargetCandidates(specifier);
			let targetExists = false;
			for (const candidate of candidates) {
				try {
					await stat(resolve(generatedDirectory, candidate));
					targetExists = true;
					break;
				} catch {
					// Try the next extension candidate.
				}
			}
			if (!targetExists) {
				failures.push(`${barrel}: missing generated target ${specifier}`);
			}
		}
	}

	try {
		const tsc = await resolvePackageExecutable("typescript", "tsc");
		await runCommand(
			tsc.command,
			[...tsc.args, "--noEmit", "--pretty", "false", "-p", "./tsconfig.json"],
			packageRoot,
		);
	} catch (error) {
		failures.push(
			`curated barrel TypeScript check failed: ${
				error instanceof Error ? error.message : String(error)
			}`,
		);
	}

	return failures;
}

/**
 * Resolve a package's JavaScript bin entry and invoke it through Node. Calling
 * the bin entry directly avoids npm's platform-specific `.cmd`/shell shims
 * without ever interpolating arguments into a shell command.
 */
export async function resolvePackageExecutable(packageName, binName) {
	let packageJsonPath;
	try {
		packageJsonPath = require.resolve(`${packageName}/package.json`);
	} catch (error) {
		throw new Error(
			`Unable to resolve ${packageName} package metadata: ${
				error instanceof Error ? error.message : String(error)
			}`,
			{ cause: error },
		);
	}

	let packageJson;
	try {
		packageJson = JSON.parse(await readFile(packageJsonPath, "utf8"));
	} catch (error) {
		throw new Error(
			`Unable to read ${packageName} package metadata: ${
				error instanceof Error ? error.message : String(error)
			}`,
			{ cause: error },
		);
	}
	const packageBin = packageJson.bin;
	const binary = isString(packageBin)
		? packageBin
		: (packageBin?.[binName] ?? packageBin?.[packageName]);

	if (!isString(binary) || binary.length === 0) {
		throw new Error(
			`Package ${packageName} does not declare a ${binName} executable`,
		);
	}

	return {
		command: process.execPath,
		args: [resolve(dirname(packageJsonPath), binary)],
	};
}

function formatCommand(command, args) {
	return [command, ...args]
		.map((part) => JSON.stringify(String(part)))
		.join(" ");
}

export function runCommand(
	command,
	args,
	cwd,
	{
		timeout = DEFAULT_COMMAND_TIMEOUT_MS,
		killSignal = DEFAULT_COMMAND_KILL_SIGNAL,
	} = {},
) {
	const commandTimeout =
		Number.isFinite(timeout) && timeout > 0
			? Math.floor(timeout)
			: DEFAULT_COMMAND_TIMEOUT_MS;
	const displayCommand = formatCommand(command, args);

	return new Promise((resolvePromise, reject) => {
		let output = "";
		let timedOut = false;
		let settled = false;
		let timeoutHandle;
		let gracePeriodHandle;

		const finish = (callback) => {
			if (settled) return;
			settled = true;
			if (timeoutHandle) clearTimeout(timeoutHandle);
			if (gracePeriodHandle) clearTimeout(gracePeriodHandle);
			callback();
		};
		const rejectWithMessage = (status, cause) => {
			finish(() =>
				reject(
					new Error(
						[`${displayCommand} failed: ${status}`, output.trim()]
							.filter(Boolean)
							.join("\n"),
						{ cause },
					),
				),
			);
		};

		let child;
		try {
			child = spawn(command, args, {
				cwd,
				stdio: ["ignore", "pipe", "pipe"],
				shell: false,
				timeout: commandTimeout,
				killSignal,
			});
		} catch (error) {
			rejectWithMessage(
				`could not start: ${error instanceof Error ? error.message : String(error)}`,
				error,
			);
			return;
		}

		timeoutHandle = setTimeout(
			() => {
				if (child.exitCode === null && child.signalCode === null) {
					timedOut = true;
					child.kill(killSignal);

					if (killSignal !== "SIGKILL") {
						gracePeriodHandle = setTimeout(() => {
							if (child.exitCode === null && child.signalCode === null) {
								child.kill("SIGKILL");
							}
						}, SIGKILL_GRACE_PERIOD_MS);
					}
				}
			},
			Math.max(1, commandTimeout - 1),
		);
		child.stdout.on("data", (chunk) => {
			output += chunk;
		});
		child.stderr.on("data", (chunk) => {
			output += chunk;
		});
		child.once("error", (error) => {
			const code = error?.code ? ` (${error.code})` : "";
			rejectWithMessage(`could not start${code}: ${error.message}`, error);
		});
		child.once("close", (code, signal) => {
			if (timedOut) {
				rejectWithMessage(
					`timed out after ${commandTimeout}ms; sent ${String(killSignal)}`,
				);
				return;
			}
			if (code === 0) {
				finish(resolvePromise);
				return;
			}
			rejectWithMessage(
				signal ? `terminated by signal ${signal}` : `exited with code ${code}`,
			);
		});
	});
}

async function readNormalizedSpec() {
	const specPath = resolve(repositoryRoot, "openapi-spec.json");
	const source = JSON.parse(await readFile(specPath, "utf8"));
	const normalized = fixOpenAPISpec(source);
	validateOpenAPISpec(normalized);
	return {
		normalized,
		normalizationDrift: JSON.stringify(source) !== JSON.stringify(normalized),
	};
}

async function createFixtureRepository(normalizedSpec) {
	const root = await mkdtemp(join(tmpdir(), "hevy-generated-client-check-"));
	try {
		const fixtureClient = resolve(root, "packages/hevy-client");
		await cp(clientRoot, fixtureClient, {
			recursive: true,
			filter: (path) => !isNodeModulesPath(path),
		});
		await rm(resolve(fixtureClient, generatedRelative), {
			recursive: true,
			force: true,
		});
		await cp(
			resolve(repositoryRoot, "tsconfig.base.json"),
			resolve(root, "tsconfig.base.json"),
		);
		await cp(
			resolve(repositoryRoot, ".oxfmtrc.json"),
			resolve(root, ".oxfmtrc.json"),
		);
		// Kubb loads the copied config from the temporary tree, so expose the
		// repository dependencies there without copying the entire installation.
		await symlink(
			resolve(repositoryRoot, "node_modules"),
			resolve(root, "node_modules"),
			"junction",
		);
		await writeFile(
			resolve(root, "openapi-spec.json"),
			JSON.stringify(normalizedSpec, null, "\t"),
		);
		return { root, client: fixtureClient };
	} catch (error) {
		await rm(root, { recursive: true, force: true });
		throw error;
	}
}

/**
 * Regenerate the checked contract in a temporary repository copy. Running
 * Kubb with the checked-in config is important: a future path regression must
 * create the fixture's root `src/` tree and fail this check.
 */
export async function checkGeneratedClient() {
	const { normalized, normalizationDrift } = await readNormalizedSpec();
	let fixture;
	try {
		fixture = await createFixtureRepository(normalized);
		const kubb = await resolvePackageExecutable("@kubb/cli", "kubb");
		const oxfmt = await resolvePackageExecutable("oxfmt", "oxfmt");
		await runCommand(
			kubb.command,
			[...kubb.args, "generate", "--config", "./kubb.config.ts"],
			fixture.client,
		);
		await runCommand(
			oxfmt.command,
			[...oxfmt.args, "--write", generatedRelative],
			fixture.client,
		);

		const failures = [];
		if (normalizationDrift) {
			failures.push(
				"checked OpenAPI spec is not normalized; run npm run openapi for a reviewed refresh",
			);
		}
		const rootSourceFiles = await findForbiddenRootSourceFiles(fixture.root);
		if (rootSourceFiles.length > 0) {
			failures.push(
				`forbidden root src creation: ${rootSourceFiles.join(", ")}`,
			);
		}
		failures.push(
			...(await compareDirectoryTrees(
				generatedRoot,
				resolve(fixture.client, generatedRelative),
			)),
		);
		failures.push(...(await findCuratedBarrelDrift(fixture.client)));

		if (failures.length > 0) {
			throw new Error(
				[
					"Generated client regeneration drift detected.",
					...failures.map((failure) => `- ${failure}`),
				].join("\n"),
			);
		}

		return { generatedFiles: (await collectFiles(generatedRoot)).length };
	} finally {
		if (fixture) {
			await rm(fixture.root, { recursive: true, force: true });
		}
	}
}

if (
	process.argv[1] &&
	fileURLToPath(import.meta.url) === resolve(process.argv[1])
) {
	try {
		const result = await checkGeneratedClient();
		console.log(
			`Generated client is up to date (${result.generatedFiles} files); no root src tree was created.`,
		);
	} catch (error) {
		console.error(error instanceof Error ? error.message : error);
		process.exitCode = 1;
	}
}

## Migration: `@kubb/plugin-zod` [​](#migration-kubb-plugin-zod)

Part of the [v4 → v5 migration guide](/docs/5.x/migration). See the full option reference in [`@kubb/plugin-zod`](/plugins/plugin-zod/).

## Zod v3 no longer supported [​](#zod-v3-no-longer-supported)

The `version` option (`'3' | '4'`) is removed. v5 always generates [Zod v4](https://zod.dev) schemas.

Upgrade your `zod` dependency:

bunpnpmnpmyarn

shell

```
bun add zod@^4
```

shell

```
pnpm add zod@^4
```

shell

```
npm install zod@^4
```

shell

```
yarn add zod@^4
```

## Removed: `mapper` [​](#removed-mapper)

v5 removes `mapper` with no drop-in replacement. Customize schema naming through the [`resolver`](/docs/5.x/guide/going-further/resolvers) option, or rewrite a schema before printing with [`macros`](/plugins/plugin-zod/reference/options#macros).

## Removed: `typed` [​](#removed-typed)

In v4, `typed: true` annotated each schema with a `ToZod` type from the matching `@kubb/plugin-ts` output. v5 removes the option. To keep a type next to each schema, use [`inferred: true`](/plugins/plugin-zod/reference/options#inferred), which exports a `z.infer` alias instead.

kubb.config.ts

diff

```
pluginZod({
  typed: true,
  inferred: true,
})
```

## Removed: `wrapOutput` [​](#removed-wrapoutput)

The `wrapOutput` callback only fired on object property values, so a top-level string, enum, or union was never wrapped. v5 removes it for a [`printer`](/plugins/plugin-zod/reference/options#printer) override, which targets any node type.

kubb.config.ts

diff

```
pluginZod({
  wrapOutput: ({ output, schema }) => `${output}.openapi(${JSON.stringify({ description: schema.description })})`,
  printer: {
    nodes: {
      object(node) {
        return `${this.base(node)}.openapi(${JSON.stringify({ description: node.description })})`
      },
    },
  },
})
```

## Removed: `operations` [​](#removed-operations)

The `operations` option is gone, so `plugin-zod` no longer emits an `operations.ts` file with the `operations` and `paths` maps. To rebuild it, add a small custom plugin that reuses the Zod resolver, so schema names stay in sync. See [Creating plugins](/docs/5.x/guide/going-further/creating-plugins) for the plugin API.

Show the operations rebuild plugin

operationsPlugin.tskubb.config.ts

typescript

```
import { ast, defineGenerator, definePlugin } from 'kubb/kit'
import { pluginZodName, type ResolverZod } from '@kubb/plugin-zod'

const operationSchemaType = `{
  readonly request: z.ZodTypeAny | undefined
  readonly parameters: {
    readonly path: z.ZodTypeAny | undefined
    readonly query: z.ZodTypeAny | undefined
    readonly header: z.ZodTypeAny | undefined
  }
  readonly responses: {
    readonly [status: number]: z.ZodTypeAny
    readonly default: z.ZodTypeAny
  }
  readonly errors: {
    readonly [status: number]: z.ZodTypeAny
  }
}`

function renderKey(key: string): string {
  if (/^\d+$/.test(key)) return key
  if (/^[A-Za-z_$][\w$]*$/.test(key)) return key
  return JSON.stringify(key)
}

function renderObject(value: unknown, pad: string): string {
  if (value === null) return 'null'
  if (typeof value !== 'object') return String(value)

  const entries = Object.entries(value as Record<string, unknown>)
  if (entries.length === 0) return '{}'

  const inner = `${pad}  `
  const body = entries
    .map(([key, val]) => {
      const rendered = typeof val === 'string' ? val : renderObject(val, inner)
      return `${inner}${renderKey(key)}: ${rendered}`
    })
    .join(',\n')

  return `{\n${body}\n${pad}}`
}

function buildSchemaNames(node: ast.OperationNode, resolver: ResolverZod) {
  const pathParam = node.parameters.find((p) => p.in === 'path')
  const queryParam = node.parameters.find((p) => p.in === 'query')
  const headerParam = node.parameters.find((p) => p.in === 'header')

  const responses: Record<number | string, string> = {}
  const errors: Record<number | string, string> = {}

  for (const res of node.responses) {
    const statusNum = Number(res.statusCode)
    if (Number.isNaN(statusNum)) continue

    const name = resolver.response.status(node, res.statusCode)
    responses[statusNum] = name
    if (statusNum >= 400) errors[statusNum] = name
  }

  responses['default'] = resolver.response.response(node)

  return {
    request: node.requestBody?.content?.[0]?.schema ? resolver.response.body(node) : null,
    parameters: {
      path: pathParam ? resolver.param.path(node, pathParam) : null,
      query: queryParam ? resolver.param.query(node, queryParam) : null,
      header: headerParam ? resolver.param.headers(node, headerParam) : null,
    },
    responses,
    errors,
  }
}

export const pluginZodOperations = definePlugin(() => ({
  name: 'plugin-zod-operations',
  hooks: {
    'kubb:plugin:setup'(ctx) {
      ctx.addGenerator(
        defineGenerator({
          name: 'zod-operations',
          operations(nodes, gctx) {
            const resolver = gctx.getResolver(pluginZodName)
            const zodOptions = gctx.requirePlugin(pluginZodName).options ?? {}
            const output = zodOptions.output ?? { path: 'zod' }
            const group = zodOptions.group ?? undefined
            const importPath = zodOptions.importPath ?? 'zod'

            const operationsFile = resolver.file({ name: 'operations', extname: '.ts', root: gctx.root, output, group })
            const transformed = nodes.filter(ast.isHttpOperationNode).map((node) => ({ node, data: buildSchemaNames(node, resolver) }))

            const imports = transformed.flatMap(({ node, data }) => {
              const names = [data.request, ...Object.values(data.responses), ...Object.values(data.parameters)].filter(Boolean) as Array<string>
              const opFile = resolver.file({ name: node.operationId, extname: '.ts', tag: node.tags[0] ?? 'default', path: node.path, root: gctx.root, output, group })

              return ast.factory.createImport({ name: names, path: opFile.path, root: operationsFile.path })
            })

            const operations: Record<string, unknown> = {}
            const paths: Record<string, Record<string, string>> = {}
            for (const { node, data } of transformed) {
              operations[node.operationId] = data
              paths[node.path] = { ...(paths[node.path] ?? {}), [node.method]: `operations[${JSON.stringify(node.operationId)}]` }
            }

            return [
              ast.factory.createFile({
                baseName: operationsFile.baseName,
                path: operationsFile.path,
                imports: [ast.factory.createImport({ name: ['z'], path: importPath, isTypeOnly: true }), ...imports],
                sources: [
                  ast.factory.createSource({
                    name: 'OperationSchema',
                    isExportable: true,
                    isIndexable: true,
                    nodes: [ast.factory.createText(`export type OperationSchema = ${operationSchemaType}`)],
                  }),
                  ast.factory.createSource({
                    name: 'OperationsMap',
                    isExportable: true,
                    isIndexable: true,
                    nodes: [ast.factory.createText('export type OperationsMap = Record<string, OperationSchema>')],
                  }),
                  ast.factory.createSource({
                    name: 'operations',
                    isExportable: true,
                    isIndexable: true,
                    nodes: [ast.factory.createText(`export const operations = ${renderObject(operations, '')} as const`)],
                  }),
                  ast.factory.createSource({
                    name: 'paths',
                    isExportable: true,
                    isIndexable: true,
                    nodes: [ast.factory.createText(`export const paths = ${renderObject(paths, '')} as const`)],
                  }),
                ],
              }),
            ]
          },
        }),
      )
    },
  },
}))
```

typescript

```
import { defineConfig } from 'kubb/config'
import { pluginTs } from '@kubb/plugin-ts'
import { pluginZod } from '@kubb/plugin-zod'
import { pluginZodOperations } from './operationsPlugin.ts'

export default defineConfig({
  input: './petStore.yaml',
  output: { path: './src/gen' },
  plugins: [pluginTs(), pluginZod(), pluginZodOperations()],
})
```

The custom plugin runs after `pluginZod`, so the per-operation schemas it imports already exist.

## Renamed: `transformers.name` [​](#renamed-transformers-name)

[`resolver.name`](/docs/5.x/migration#transformersname-resolver) replaces `transformers.name`, covered in full by [Override a resolver](/docs/5.x/guide/going-further/resolvers). The v4 `transformers.schema` callback maps to [`macros`](/docs/5.x/migration#transformersschema-macros).

## Moved to `adapterOas` [​](#moved-to-adapteroas)

`dateType`, `integerType`, `unknownType`, and `emptySchemaType` moved to [`adapterOas`](/adapters/adapter-oas/). See [Migration: @kubb/adapter-oas](/docs/5.x/migration/adapter-oas).

## Changed: inferred type names end with `Type` [​](#changed-inferred-type-names-end-with-type)

With `inferred: true`, the `z.infer<typeof schema>` alias now carries a `SchemaType` suffix. `petSchema` exports `PetSchemaType` instead of `PetSchema`.

In v4 the value and its inferred type differed only by casing (`petSchema` / `PetSchema`), so an all-uppercase name like `SUV`, `URL`, or `API` produced the same identifier for both. The barrel then re-exported it twice and failed with `TS2300: Duplicate identifier`. The `Type` suffix keeps them apart at any casing.

zod/petSchema.ts

diff

```
export const petSchema = z.object({
  name: z.string(),
  status: z.enum(['available', 'pending', 'sold']).optional(),
})

export type PetSchemaType = z.infer<typeof petSchema>
export type PetSchema = z.infer<typeof petSchema>
```

Update any imports that referenced the old name:

Update imports

diff

```
import type { PetSchemaType } from './gen/zod/petSchema.ts'
import type { PetSchema } from './gen/zod/petSchema.ts'
```

## Generated output [​](#generated-output)

### Response schema names gain a `Status<code>` segment [​](#response-schema-names-gain-a-status-code-segment)

Response schema names now include a `Status<code>` segment. `listPets200Schema` becomes `listPetsStatus200Schema`. Update any imports that referenced the old name.

Update imports

diff

```
import { listPets200Schema } from './gen/zod'
import { listPetsStatus200Schema } from './gen/zod'
```

### Chained syntax instead of functional wrappers [​](#chained-syntax-instead-of-functional-wrappers)

v5 prefers the chained Zod 4 syntax. `.optional()` sits at the end of the chain, right before `.describe()`.

Generated output

diff

```
id: z.optional(z.int()),
shipDate: z.optional(z.iso.datetime()),
status: z.optional(z.enum(['placed', 'approved']).describe('Order Status')),
id: z.int().optional(),
shipDate: z.iso.datetime().optional(),
status: z.enum(['placed', 'approved']).optional().describe('Order Status'),
```

The functional form (`z.optional(...)`) is now reserved for `mini: true` output, which imports from `zod/mini`.

### Self-referencing getters only for true cycles [​](#self-referencing-getters-only-for-true-cycles)

v4 wrapped almost every nested ref in a getter. v5 does so only when the schema is truly circular, meaning it references itself or its parent.

Diff

diff

```
 get category() {
   return categorySchema.optional()
 },
 get tags() {
   return z.array(tagSchema).optional()
 },
 category: categorySchema.optional(),
 tags: z.array(tagSchema).optional(),
  get parent() {
    return z.array(petSchema).optional()
  },
```

